// Core tests: the 19 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. The hand-derived values below were computed by hand from the
// SPEC's rules and cross-checked with an independent Python
// fractions.Fraction recomputation of the same pinned rules (the same
// two-method approach recorded in AUTHOR-CHECK.md).

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatMoneyMilliNt,
  formatUsage,
  run,
} from "../public/js/core/taiwan-water-bill.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  cycle: "bimonthly",
  diameterMm: "20",
  usageM3: "30",
  sewerRateNt: "",
  wasteRateNt: "",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

function usageOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  return outcome.result;
}

test("worked anchors: monthly 1 degree is only the basic fee plus 7.35, and the .5 wrcc rounds up", () => {
  const one = usageOf({ ...base, cycle: "monthly", diameterMm: "13", usageM3: "1" });
  assert.deepEqual(one.tiers, [{ tier: 1, degrees: 1, unitPriceMilliNt: 7350, subtotalMilliNt: 7350 }]);
  assert.equal(one.basicFeeMilliNt, 17850);
  assert.equal(one.usageChargeMilliNt, 7350);
  assert.equal(one.waterSubtotalMilliNt, 25200);
  assert.equal(one.wrccMilliNt, 0);
  assert.equal(one.businessTaxMilliNt, 1200);
  assert.equal(one.totalPayableMilliNt, 25000);
  // 73500 / 21000 = 3.5 exactly, so the wrcc rounds half-up to 4.
  const ten = usageOf({ ...base, cycle: "monthly", diameterMm: "20", usageM3: "10" });
  assert.equal(ten.wrccMilliNt, 4000);
  assert.equal(ten.totalPayableMilliNt, 113000);
});

test("tier boundaries: monthly -1 / boundary / +1 usage charges", () => {
  // Tier 1/2 edge (10/11): 10 x 7.35 = 73.5; 11 adds one tier-2 degree.
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "9" }).usageChargeMilliNt, 66150);
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "10" }).usageChargeMilliNt, 73500);
  const eleven = usageOf({ ...base, cycle: "monthly", usageM3: "11" });
  assert.equal(eleven.usageChargeMilliNt, 82950);
  assert.equal(eleven.tiers.length, 2);
  assert.equal(eleven.wrccMilliNt, 4000);
  assert.equal(eleven.businessTaxMilliNt, 5700);
  assert.equal(eleven.totalPayableMilliNt, 123000);
  // Tier 2/3 edge (30/31): official 9.45 x 30 - 21 = 262.5.
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "29" }).usageChargeMilliNt, 253050);
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "30" }).usageChargeMilliNt, 262500);
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "31" }).usageChargeMilliNt, 274050);
  // Tier 3/4 edge (50/51): official 11.55 x 50 - 84 = 493.5.
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "49" }).usageChargeMilliNt, 481950);
  assert.equal(usageOf({ ...base, cycle: "monthly", usageM3: "50" }).usageChargeMilliNt, 493500);
  const fiftyOne = usageOf({ ...base, cycle: "monthly", usageM3: "51" });
  assert.equal(fiftyOne.usageChargeMilliNt, 505575);
  assert.equal(fiftyOne.tiers.length, 4);
  assert.equal(fiftyOne.wrccMilliNt, 24000);
  assert.equal(fiftyOne.businessTaxMilliNt, 25800);
  assert.equal(fiftyOne.totalPayableMilliNt, 565000);
});

test("tier boundaries: bimonthly -1 / boundary / +1 usage charges", () => {
  assert.equal(usageOf({ ...base, usageM3: "19" }).usageChargeMilliNt, 139650);
  assert.equal(usageOf({ ...base, usageM3: "20" }).usageChargeMilliNt, 147000);
  const twentyOne = usageOf({ ...base, usageM3: "21" });
  assert.equal(twentyOne.usageChargeMilliNt, 156450);
  assert.equal(twentyOne.tiers.length, 2);
  assert.equal(twentyOne.wrccMilliNt, 7000);
  assert.equal(twentyOne.businessTaxMilliNt, 10900);
  assert.equal(twentyOne.totalPayableMilliNt, 235000);
  assert.equal(usageOf({ ...base, usageM3: "59" }).usageChargeMilliNt, 515550);
  assert.equal(usageOf({ ...base, usageM3: "60" }).usageChargeMilliNt, 525000);
  assert.equal(usageOf({ ...base, usageM3: "61" }).usageChargeMilliNt, 536550);
  assert.equal(usageOf({ ...base, usageM3: "99" }).usageChargeMilliNt, 975450);
  assert.equal(usageOf({ ...base, usageM3: "100" }).usageChargeMilliNt, 987000);
  const hundredOne = usageOf({ ...base, usageM3: "101" });
  assert.equal(hundredOne.usageChargeMilliNt, 999075);
  assert.equal(hundredOne.tiers.length, 4);
  assert.equal(hundredOne.wrccMilliNt, 48000);
  assert.equal(hundredOne.businessTaxMilliNt, 51000);
  assert.equal(hundredOne.totalPayableMilliNt, 1118000);
});

test("official-formula identity: tier subtotals sum to price x usage - difference", () => {
  // Bimonthly 110 degrees: 12.075 x 110 - 220.5 = 1107.75 (the official
  // example value, also the fixture's bimonthly-official-example).
  const official = usageOf({ ...base, diameterMm: "25", usageM3: "110" });
  assert.equal(official.usageChargeMilliNt, 1107750);
  assert.equal(
    official.tiers.reduce((sum, tier) => sum + tier.subtotalMilliNt, 0),
    official.usageChargeMilliNt,
  );
  // Monthly 30 degrees: 9.45 x 30 - 21 = 262.5.
  const monthly = usageOf({ ...base, cycle: "monthly", usageM3: "30" });
  assert.equal(monthly.usageChargeMilliNt, 262500);
});

test("basic fee table: all 13 diameters, both cycles, literal values", () => {
  const monthly = {
    13: 17850, 20: 35700, 25: 66150, 40: 196350, 50: 357000, 75: 963900,
    100: 1909950, 150: 5301450, 200: 10531500, 250: 18599700, 300: 29184750,
    350: 41626200, "400+": 58119600,
  };
  for (const [diameter, expected] of Object.entries(monthly)) {
    assert.equal(
      usageOf({ cycle: "monthly", diameterMm: diameter, usageM3: "0" }).basicFeeMilliNt,
      expected,
      `monthly ${diameter}`,
    );
    assert.equal(
      usageOf({ cycle: "bimonthly", diameterMm: diameter, usageM3: "0" }).basicFeeMilliNt,
      expected * 2,
      `bimonthly ${diameter}`,
    );
  }
});

test("levy rates: a zero rate is levied at zero, the max rate 99.99 works, and absent means null", () => {
  const zero = usageOf({ ...base, sewerRateNt: "0" });
  assert.equal(zero.sewerRateNt, "0");
  assert.equal(zero.sewerFeeMilliNt, 0);
  assert.equal(zero.wasteRateNt, null);
  assert.equal(zero.wasteFeeMilliNt, null);
  assert.equal(zero.totalPayableMilliNt, 325000);
  // 99.99 x 10 = 999.9 -> 1000 (half-up).
  const max = usageOf({ ...base, cycle: "monthly", usageM3: "10", wasteRateNt: "99.99" });
  assert.equal(max.wasteRateNt, "99.99");
  assert.equal(max.wasteFeeMilliNt, 1000000);
  assert.equal(max.totalPayableMilliNt, 1113000);
  // 5.005 is three decimals; 5.00 is accepted and equals 5.
  const trailing = usageOf({ ...base, sewerRateNt: "5.00" });
  assert.equal(trailing.sewerRateNt, "5.00");
  assert.equal(trailing.sewerFeeMilliNt, 150000);
});

test("legal maximum: 999,999 degrees on the smallest meter", () => {
  const max = usageOf({ cycle: "bimonthly", diameterMm: "13", usageM3: "999999" });
  assert.equal(max.tiers[3].degrees, 999899);
  assert.equal(max.tiers[3].subtotalMilliNt, 12073780425);
  assert.equal(max.usageChargeMilliNt, 12074767425);
  assert.equal(max.waterSubtotalMilliNt, 12074803125);
  assert.equal(max.wrccMilliNt, 574989000);
  assert.equal(max.businessTaxMilliNt, 574990600);
  assert.equal(max.totalPayableMilliNt, 12649792000);
});

test("capacity: a 9-unit cycle value is INPUT_LIMIT; the pinned 9-unit bimonthly value passes", () => {
  assert.deepEqual(errorOf({ ...base, cycle: "bimonthlyx" }), {
    code: "INPUT_LIMIT",
    field: "cycle",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, diameterMm: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "diameterMm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, usageM3: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "usageM3",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sewerRateNt: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "sewerRateNt",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, wasteRateNt: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "wasteRateNt",
    row: null,
  });
});

test("an unpaired surrogate is UNICODE on every field", () => {
  for (const field of ["cycle", "diameterMm", "usageM3", "sewerRateNt", "wasteRateNt"]) {
    assert.deepEqual(errorOf({ ...base, [field]: "\uD800" }), {
      code: "UNICODE",
      field,
      row: null,
    });
  }
});

test("empty required fields are EMPTY; empty optional rates mean not levied", () => {
  assert.deepEqual(errorOf({ ...base, cycle: "" }), { code: "EMPTY", field: "cycle", row: null });
  assert.deepEqual(errorOf({ ...base, diameterMm: "" }), {
    code: "EMPTY",
    field: "diameterMm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, usageM3: "" }), { code: "EMPTY", field: "usageM3", row: null });
  const emptyRates = usageOf({ ...base, sewerRateNt: "", wasteRateNt: "" });
  assert.equal(emptyRates.sewerRateNt, null);
  assert.equal(emptyRates.wasteRateNt, null);
});

test("usage grammar: decimals, signs, exponents, spaces and non-ASCII digits are INTEGER_FORMAT", () => {
  for (const bad of ["30.5", "30.0", "-30", "+30", "3e1", "30 ", " 30", "３０", "30,000", "030", "00"]) {
    assert.deepEqual(errorOf({ ...base, usageM3: bad }), {
      code: "INTEGER_FORMAT",
      field: "usageM3",
      row: null,
    });
  }
  const zero = usageOf({ ...base, usageM3: "0" });
  assert.equal(zero.usageM3, 0);
});

test("rate grammar: 5., .5, 05 and three decimals are DECIMAL_FORMAT; 100 is RANGE", () => {
  for (const bad of ["5.", ".5", "05", "5.005", "5.123", "-5", "5e1"]) {
    assert.deepEqual(errorOf({ ...base, sewerRateNt: bad }), {
      code: "DECIMAL_FORMAT",
      field: "sewerRateNt",
      row: null,
    });
  }
  assert.deepEqual(errorOf({ ...base, wasteRateNt: "100" }), {
    code: "RANGE",
    field: "wasteRateNt",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sewerRateNt: "99.995" }), {
    code: "DECIMAL_FORMAT",
    field: "sewerRateNt",
    row: null,
  });
  const ok = usageOf({ ...base, sewerRateNt: "0.05" });
  assert.equal(ok.sewerFeeMilliNt, 2000);
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, cycle: "weekly", diameterMm: "30" }), {
    code: "ENUM",
    field: "cycle",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, diameterMm: "30", usageM3: "bad" }), {
    code: "ENUM",
    field: "diameterMm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, usageM3: "bad", sewerRateNt: "bad" }), {
    code: "INTEGER_FORMAT",
    field: "usageM3",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sewerRateNt: "bad", wasteRateNt: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "sewerRateNt",
    row: null,
  });
});

test("schema: extra key, missing required key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.usageM3;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, usageM3: 30 }), schema);
  assert.deepEqual(errorOf({ ...base, sewerRateNt: 5 }), schema);
  assert.deepEqual(errorOf(["bimonthly"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("bimonthly"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "usageM3", {
    enumerable: true,
    get() {
      return "30";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.usageM3 = new String("30");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("schema: absent optional rates are accepted and read as not levied", () => {
  const minimal = { cycle: "bimonthly", diameterMm: "20", usageM3: "30" };
  const outcome = run(minimal);
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.sewerRateNt, null);
  assert.equal(outcome.result.wasteRateNt, null);
  const oneAbsent = { cycle: "bimonthly", diameterMm: "20", usageM3: "30", sewerRateNt: "5" };
  assert.equal(run(oneAbsent).result.sewerFeeMilliNt, 150000);
});

test("the core does not mutate its input", () => {
  const input = { ...base, sewerRateNt: "5" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, usageM3: "1000000" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("property: tier subtotals sum to the usage charge, and the total is always whole yuan", () => {
  for (const cycle of ["monthly", "bimonthly"]) {
    for (const usage of [0, 1, 9, 10, 11, 20, 21, 30, 31, 50, 51, 60, 61, 100, 101, 500, 999999]) {
      const result = usageOf({ cycle, diameterMm: "20", usageM3: String(usage) });
      assert.equal(
        result.tiers.reduce((sum, tier) => sum + tier.subtotalMilliNt, 0),
        result.usageChargeMilliNt,
        `${cycle} ${usage}`,
      );
      assert.equal(result.totalPayableMilliNt % 1000, 0, `${cycle} ${usage} total`);
      assert.equal(result.wrccMilliNt % 1000, 0, `${cycle} ${usage} wrcc`);
      assert.equal(result.businessTaxMilliNt % 100, 0, `${cycle} ${usage} tax`);
      if (usage === 0) assert.deepEqual(result.tiers, []);
    }
  }
});

test("property: the total equals the rounded subtotal plus the whole-yuan levies", () => {
  for (const usage of [0, 7, 30, 60, 110, 1000]) {
    for (const rates of [{}, { sewerRateNt: "5" }, { sewerRateNt: "5", wasteRateNt: "3.7" }]) {
      const result = usageOf({ ...base, usageM3: String(usage), ...rates });
      const roundedSubtotal = Math.floor((2 * result.waterSubtotalMilliNt + 1000) / 2000);
      const expected =
        (roundedSubtotal +
          result.wrccMilliNt / 1000 +
          (result.sewerFeeMilliNt ?? 0) / 1000 +
          (result.wasteFeeMilliNt ?? 0) / 1000) *
        1000;
      assert.equal(result.totalPayableMilliNt, expected);
    }
  }
});

test("display formatting: money to at most two decimals, usage grouped", () => {
  assert.equal(formatMoneyMilliNt(0), "0");
  assert.equal(formatMoneyMilliNt(35700), "35.7");
  assert.equal(formatMoneyMilliNt(241500), "241.5");
  assert.equal(formatMoneyMilliNt(1107750), "1,107.75");
  assert.equal(formatMoneyMilliNt(12075), "12.08");
  assert.equal(formatMoneyMilliNt(116239200), "116,239.2");
  assert.equal(formatMoneyMilliNt(1000000), "1,000");
  assert.equal(formatUsage(0), "0");
  assert.equal(formatUsage(30), "30");
  assert.equal(formatUsage(999999), "999,999");
});
